PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE dcrs_river_readings (
  station TEXT NOT NULL,
  timestamp TEXT NOT NULL,
  level REAL NOT NULL,
  raw_level REAL,
  trend_value REAL,
  trend TEXT NOT NULL,
  source TEXT NOT NULL,
  created_at TEXT NOT NULL,
  PRIMARY KEY (station, timestamp)
);
CREATE TABLE river_readings (
  station TEXT NOT NULL,
  timestamp TEXT NOT NULL,
  level REAL,
  raw_level REAL,
  trend_value REAL,
  trend TEXT NOT NULL,
  source TEXT NOT NULL,
  created_at TEXT NOT NULL,
  PRIMARY KEY (station, timestamp)
);
CREATE TABLE sace_readings (
  station TEXT NOT NULL,
  timestamp TEXT NOT NULL,
  level REAL NOT NULL,
  level_cm REAL NOT NULL,
  created_at TEXT NOT NULL,
  PRIMARY KEY (station, timestamp)
);
CREATE TABLE rain_readings (
  station TEXT NOT NULL,
  timestamp TEXT NOT NULL,
  rain REAL,
  level_cm REAL,
  discharge REAL,
  quality TEXT NOT NULL,
  created_at TEXT NOT NULL,
  PRIMARY KEY (station, timestamp)
);
CREATE TABLE ceran_readings (
  plant_id TEXT NOT NULL,
  timestamp TEXT NOT NULL,
  upstream_level REAL NOT NULL,
  downstream_level REAL NOT NULL,
  inflow REAL NOT NULL,
  turbined REAL NOT NULL,
  spilled REAL NOT NULL,
  residual REAL NOT NULL,
  outflow REAL NOT NULL,
  status TEXT NOT NULL,
  created_at TEXT NOT NULL,
  PRIMARY KEY (plant_id, timestamp)
);
CREATE TABLE bulletins (
  id TEXT PRIMARY KEY,
  title TEXT NOT NULL,
  published_at TEXT,
  status TEXT NOT NULL,
  href TEXT NOT NULL UNIQUE,
  created_at TEXT NOT NULL
);
CREATE TABLE alerts (
  id TEXT PRIMARY KEY,
  title TEXT NOT NULL,
  summary TEXT NOT NULL,
  published_at TEXT NOT NULL,
  valid_until TEXT NOT NULL,
  severity TEXT NOT NULL,
  href TEXT NOT NULL,
  created_at TEXT NOT NULL
);
